input = sys.stdin.readline

def bit_add(t, i, x):
    n = len(t) - 1
    while i <= n:
        t[i] += x
        i += i & -i

def bit_sum(t, i):
    s = 0
    while i > 0:
        s += t[i]
        i -= i & -i
    return s

n, q = map(int, input().split())
a = list(map(int, input().split()))
ops = [list(map(int, input().split())) for _ in range(q)]

t = [0] * (n + 1)
for i in range(n):
    bit_add(t, i + 1, a[i])
out = []
for kind, x, y in ops:
    if kind == 1:
        bit_add(t, x, y)
    else:
        out.append(bit_sum(t, y) - bit_sum(t, x - 1))
print(*out)

